1	package api
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"net/http"
10		"net/url"
11		"runtime"
12		"strings"
13	
14		"github.com/GopeedLab/gopeed/pkg/base"
15		"github.com/GopeedLab/gopeed/pkg/download"
16		restmodel "github.com/GopeedLab/gopeed/pkg/rest/model"
17	)
18	
19	type Context struct {
20		Method     string
21		Path       string
22		Query      url.Values
23		Body       []byte
24		Headers    http.Header
25		PathParams map[string]string
26	}
27	
28	func (c *Context) PathParam(name string) string {
29		if c == nil || c.PathParams == nil {
30			return ""
31		}
32		return c.PathParams[name]
33	}
34	
35	type Response struct {
36		StatusCode int
37		Body       any
38	}
39	
40	type Service struct {
41		Downloader *download.Downloader
42		routes     []RouteSpec
43		taskEvents taskEventSubscription
44	}
45	
46	func NewService(downloader *download.Downloader) (*Service, error) {
47		if downloader == nil {
48			return nil, fmt.Errorf("downloader is nil")
49		}
50		service := &Service{Downloader: downloader}
51		service.routes = []RouteSpec{
52			newRoute(http.MethodGet, "/api/v1/info", service.info),
53			newRoute(http.MethodPost, "/api/v1/resolve", service.resolve),
54			newRoute(http.MethodPost, "/api/v1/tasks", service.createTask),
55			newRoute(http.MethodPost, "/api/v1/tasks/batch", service.createTaskBatch),
56			newRoute(http.MethodPatch, "/api/v1/tasks/{id}", service.patchTask),
57			newRoute(http.MethodPut, "/api/v1/tasks/{id}/pause", service.pauseTask),
58			newRoute(http.MethodPut, "/api/v1/tasks/pause", service.pauseTasks),
59			newRoute(http.MethodPut, "/api/v1/tasks/{id}/continue", service.continueTask),
60			newRoute(http.MethodPut, "/api/v1/tasks/continue", service.continueTasks),
61			newRoute(http.MethodDelete, "/api/v1/tasks/{id}", service.deleteTask),
62			newRoute(http.MethodDelete, "/api/v1/tasks", service.deleteTasks),
63			newRoute(http.MethodGet, "/api/v1/tasks/{id}", service.getTask),
64			newRoute(http.MethodGet, "/api/v1/tasks/{id}/status", service.getTaskStatus),
65			newRoute(http.MethodGet, "/api/v1/tasks", service.getTasks),
66			newRoute(http.MethodGet, "/api/v1/tasks/{id}/stats", service.getStats),
67			newRoute(http.MethodPost, "/api/v1/protocols/{protocol}/jobs/{name}/trigger", service.triggerProtocolJob),
68			newRoute(http.MethodPost, "/api/v1/mirrors/{provider}/candidates", service.mirrorCandidates),
69			newRoute(http.MethodGet, "/api/v1/config", service.getConfig),
70			newRoute(http.MethodPut, "/api/v1/config", service.putConfig),
71			newRoute(http.MethodPost, "/api/v1/extensions", service.installExtension),
72			newRoute(http.MethodGet, "/api/v1/extensions", service.getExtensions),
73			newRoute(http.MethodGet, "/api/v1/extensions/{identity}", service.getExtension),
74			newRoute(http.MethodPut, "/api/v1/extensions/{identity}/settings", service.updateExtensionSettings),
75			newRoute(http.MethodPut, "/api/v1/extensions/{identity}/switch", service.switchExtension),
76			newRoute(http.MethodDelete, "/api/v1/extensions/{identity}", service.deleteExtension),
77			newRoute(http.MethodGet, "/api/v1/extensions/{identity}/update", service.updateCheckExtension),
78			newRoute(http.MethodPost, "/api/v1/extensions/{identity}/update", service.updateExtension),
79			newRoute(http.MethodPost, "/api/v1/webhook/test", service.testWebhook),
80		}
81		if err := validateRoutes(service.routes); err != nil {
82			return nil, err
83		}
84		downloader.Listener(service.emitTaskEvent)
85		return service, nil
86	}
87	
88	func (s *Service) RouteSpecs() []RouteSpec {
89		return append([]RouteSpec(nil), s.routes...)
90	}
91	
92	func (s *Service) Dispatch(method, rawPath string, query url.Values, body []byte, headers http.Header) (response *Response) {
93		defer func() {
94			if recovered := recover(); recovered != nil {
95				response = newErrorResponse(fmt.Sprintf("%v", recovered))
96			}
97		}()
98	
99		method = strings.ToUpper(strings.TrimSpace(method))
100		path := cleanPath(rawPath)
101		for _, route := range s.routes {
102			if route.Method != method {
103				continue
104			}
105			pathParams, matched := route.Match(path)
106			if !matched {
107				continue
108			}
109			return route.Handler(&Context{
110				Method:     method,
111				Path:       path,
112				Query:      query,
113				Body:       body,
114				Headers:    headers,
115				PathParams: pathParams,
116			})
117		}
118		return newStatusResponse(http.StatusNotFound, restmodel.NewErrorResult("not found"))
119	}
120	
121	func (s *Service) JSON(method, rawPath string, query url.Values, body []byte, headers http.Header) (int, []byte) {
122		response := s.Dispatch(method, rawPath, query, body, headers)
123		data, err := json.Marshal(response.Body)
124		if err != nil {
125			response = newErrorResponse(err.Error())
126			data, _ = json.Marshal(response.Body)
127		}
128		return response.StatusCode, data
129	}
130	
131	func (s *Service) info(_ *Context) *Response {
132		return newOKResponse(map[string]any{
133			"version":  base.Version,
134			"runtime":  runtime.Version(),
135			"os":       runtime.GOOS,
136			"arch":     runtime.GOARCH,
137			"inDocker": base.InDocker == "true",
138		})
139	}
140	
141	func (s *Service) resolve(ctx *Context) *Response {
142		var request restmodel.ResolveTask
143		if response := decodeRequest(ctx.Body, &request); response != nil {
144			return response
145		}
146		result, err := s.Downloader.Resolve(request.Req)
147		if err != nil {
148			return newErrorResponse(err.Error())
149		}
150		return newOKResponse(result)
151	}
152	
153	func (s *Service) createTask(ctx *Context) *Response {
154		var request restmodel.CreateTask
155		if response := decodeRequest(ctx.Body, &request); response != nil {
156			return response
157		}
158		var (
159			taskID string
160			err    error
161		)
162		if request.Rid != "" {
163			taskID, err = s.Downloader.CreateWithOptions(request.Rid, request.Opts)
164		} else if request.Req != nil {
165			taskID, err = s.Downloader.CreateDirect(request.Req, request.Opts)
166		} else {
167			return newErrorResponse("param invalid: rid or req", restmodel.CodeInvalidParam)
168		}
169		if err != nil {
170			return newErrorResponse(err.Error())
171		}
172		return newOKResponse(taskID)
173	}
174	
175	func (s *Service) createTaskBatch(ctx *Context) *Response {
176		var request base.CreateTaskBatch
177		if response := decodeRequest(ctx.Body, &request); response != nil {
178			return response
179		}
180		if len(request.Reqs) == 0 {
181			return newErrorResponse("param invalid: reqs", restmodel.CodeInvalidParam)
182		}
183		result, err := s.Downloader.CreateDirectBatchWithResult(&request)
184		if err != nil {
185			return newErrorResponse(err.Error())
186		}
187		return newOKResponse(result)
188	}
189	
190	func (s *Service) patchTask(ctx *Context) *Response {
191		taskID := ctx.PathParam("id")
192		if taskID == "" {
193			return invalidIDResponse()
194		}
195		var request restmodel.PatchTask
196		if response := decodeRequest(ctx.Body, &request); response != nil {
197			return response
198		}
199		if err := s.Downloader.Patch(taskID, request.Req, request.Opts); err != nil {
200			if err == download.ErrTaskNotFound {
201				return taskNotFoundResponse()
202			}
203			return newErrorResponse(err.Error())
204		}
205		return newNilResponse()
206	}
207	
208	func (s *Service) pauseTask(ctx *Context) *Response {
209		return s.applyTaskAction(ctx, s.Downloader.Pause)
210	}
211	
212	func (s *Service) pauseTasks(ctx *Context) *Response {
213		return applyFilterAction(taskFilterFromQuery(ctx.Query), s.Downloader.Pause)
214	}
215	
216	func (s *Service) continueTask(ctx *Context) *Response {
217		return s.applyTaskAction(ctx, s.Downloader.Continue)
218	}
219	
220	func (s *Service) continueTasks(ctx *Context) *Response {
221		return applyFilterAction(taskFilterFromQuery(ctx.Query), s.Downloader.Continue)
222	}
223	
224	func (s *Service) applyTaskAction(ctx *Context, action func(*download.TaskFilter) error) *Response {
225		taskID := ctx.PathParam("id")
226		if taskID == "" {
227			return invalidIDResponse()
228		}
229		return applyFilterAction(&download.TaskFilter{IDs: []string{taskID}}, action)
230	}
231	
232	func applyFilterAction(filter *download.TaskFilter, action func(*download.TaskFilter) error) *Response {
233		if err := action(filter); err != nil {
234			return newErrorResponse(err.Error())
235		}
236		return newNilResponse()
237	}
238	
239	func (s *Service) deleteTask(ctx *Context) *Response {
240		taskID := ctx.PathParam("id")
241		if taskID == "" {
242			return invalidIDResponse()
243		}
244		return deleteTasks(s.Downloader, &download.TaskFilter{IDs: []string{taskID}}, ctx.Query.Get("force") == "true")
245	}
246	
247	func (s *Service) deleteTasks(ctx *Context) *Response {
248		return deleteTasks(s.Downloader, taskFilterFromQuery(ctx.Query), ctx.Query.Get("force") == "true")
249	}
250	
251	func deleteTasks(downloader *download.Downloader, filter *download.TaskFilter, force bool) *Response {
252		if err := downloader.Delete(filter, force); err != nil {
253			return newErrorResponse(err.Error())
254		}
255		return newNilResponse()
256	}
257	
258	func (s *Service) getTask(ctx *Context) *Response {
259		taskID := ctx.PathParam("id")
260		if taskID == "" {
261			return invalidIDResponse()
262		}
263		task := s.Downloader.GetTask(taskID)
264		if task == nil {
265			return taskNotFoundResponse()
266		}
267		return newOKResponse(task)
268	}
269	
270	func (s *Service) getTaskStatus(ctx *Context) *Response {
271		taskID := ctx.PathParam("id")
272		if taskID == "" {
273			return invalidIDResponse()
274		}
275		status, err := s.Downloader.RuntimeStatus(taskID)
276		if err != nil {
277			if err == download.ErrTaskNotFound {
278				return taskNotFoundResponse()
279			}
280			return newErrorResponse(err.Error())
281		}
282		return newOKResponse(status)
283	}
284	
285	func (s *Service) getTasks(ctx *Context) *Response {
286		return newOKResponse(s.Downloader.GetTasksByFilter(taskFilterFromQuery(ctx.Query)))
287	}
288	
289	func (s *Service) getStats(ctx *Context) *Response {
290		taskID := ctx.PathParam("id")
291		if taskID == "" {
292			return invalidIDResponse()
293		}
294		stats, err := s.Downloader.Stats(taskID)
295		if err != nil {
296			return newErrorResponse(err.Error())
297		}
298		return newOKResponse(stats)
299	}
300	
301	func (s *Service) triggerProtocolJob(ctx *Context) *Response {
302		if err := s.Downloader.TriggerProtocolJob(context.Background(), ctx.PathParam("protocol"), ctx.PathParam("name")); err != nil {
303			status := http.StatusBadRequest
304			if errors.Is(err, download.ErrUnSupportedProtocol) || errors.Is(err, download.ErrProtocolJobNotFound) {
305				status = http.StatusNotFound
306			}
307			return newStatusResponse(status, restmodel.NewErrorResult(err.Error()))
308		}
309		return newNilResponse()
310	}
311	
