46	func NewService(downloader *download.Downloader) (*Service, error) {
47		if downloader == nil {
48			return nil, fmt.Errorf("downloader is nil")
49		}
50		service := &Service{Downloader: downloader}
51		service.routes = []RouteSpec{
52			newRoute(http.MethodGet, "/api/v1/info", service.info),
53			newRoute(http.MethodPost, "/api/v1/resolve", service.resolve),
54			newRoute(http.MethodPost, "/api/v1/tasks", service.createTask),
55			newRoute(http.MethodPost, "/api/v1/tasks/batch", service.createTaskBatch),
56			newRoute(http.MethodPatch, "/api/v1/tasks/{id}", service.patchTask),
57			newRoute(http.MethodPut, "/api/v1/tasks/{id}/pause", service.pauseTask),
58			newRoute(http.MethodPut, "/api/v1/tasks/pause", service.pauseTasks),
59			newRoute(http.MethodPut, "/api/v1/tasks/{id}/continue", service.continueTask),
60			newRoute(http.MethodPut, "/api/v1/tasks/continue", service.continueTasks),
61			newRoute(http.MethodDelete, "/api/v1/tasks/{id}", service.deleteTask),
62			newRoute(http.MethodDelete, "/api/v1/tasks", service.deleteTasks),
63			newRoute(http.MethodGet, "/api/v1/tasks/{id}", service.getTask),
64			newRoute(http.MethodGet, "/api/v1/tasks/{id}/status", service.getTaskStatus),
65			newRoute(http.MethodGet, "/api/v1/tasks", service.getTasks),
66			newRoute(http.MethodGet, "/api/v1/tasks/{id}/stats", service.getStats),
67			newRoute(http.MethodPost, "/api/v1/protocols/{protocol}/jobs/{name}/trigger", service.triggerProtocolJob),
68			newRoute(http.MethodPost, "/api/v1/mirrors/{provider}/candidates", service.mirrorCandidates),
69			newRoute(http.MethodGet, "/api/v1/config", service.getConfig),
70			newRoute(http.MethodPut, "/api/v1/config", service.putConfig),
71			newRoute(http.MethodPost, "/api/v1/extensions", service.installExtension),
72			newRoute(http.MethodGet, "/api/v1/extensions", service.getExtensions),
73			newRoute(http.MethodGet, "/api/v1/extensions/{identity}", service.getExtension),
74			newRoute(http.MethodPut, "/api/v1/extensions/{identity}/settings", service.updateExtensionSettings),
75			newRoute(http.MethodPut, "/api/v1/extensions/{identity}/switch", service.switchExtension),
76			newRoute(http.MethodDelete, "/api/v1/extensions/{identity}", service.deleteExtension),
77			newRoute(http.MethodGet, "/api/v1/extensions/{identity}/update", service.updateCheckExtension),
