92	func (s *Service) Dispatch(method, rawPath string, query url.Values, body []byte, headers http.Header) (response *Response) {
93		defer func() {
94			if recovered := recover(); recovered != nil {
95				response = newErrorResponse(fmt.Sprintf("%v", recovered))
96			}
97		}()
98	
99		method = strings.ToUpper(strings.TrimSpace(method))
100		path := cleanPath(rawPath)
101		for _, route := range s.routes {
102			if route.Method != method {
103				continue
104			}
105			pathParams, matched := route.Match(path)
106			if !matched {
107				continue
108			}
109			return route.Handler(&Context{
110				Method:     method,
111				Path:       path,
112				Query:      query,
113				Body:       body,
114				Headers:    headers,
115				PathParams: pathParams,
116			})
117		}
118		return newStatusResponse(http.StatusNotFound, restmodel.NewErrorResult("not found"))
119	}
