57			Req: &base.Request{URL: upstream.URL},
58		})
59		if resolved.ID == "" || resolved.Res.Size != 4 || resolved.Res.Files[0].Name != "payload.txt" {
60			t.Fatalf("unexpected resolved resource: %+v", resolved)
61		}
62		dir := filepath.Join(t.TempDir(), "chosen-after-resolve")
63		opts := &base.Options{Path: dir, Name: "renamed.txt", SelectFiles: []int{0}}
64		id := serviceTestRequest[string](t, service, http.MethodPost, "/api/v1/tasks", &restmodel.CreateTask{Rid: resolved.ID, Opts: opts})
65		task := serviceTestRequest[*download.Task](t, service, http.MethodGet, "/api/v1/tasks/"+id, nil)
66		if task.Meta.Opts.Path != dir || task.Meta.Opts.Name != opts.Name || !reflect.DeepEqual(task.Meta.Opts.SelectFiles, opts.SelectFiles) {
67			t.Fatalf("creation lost submitted download options: %+v", task.Meta.Opts)
68		}
69	}
